/**
 * REDHAT-FIX-05: REVIEW approval must re-run the canonical geometry gate.
 *
 * Pure-logic unit tests for the gate evaluation that approveDisposition
 * must perform before writing verdict:'pass' / riderReady:true.
 */

import { describe, expect, it } from 'vitest'
import { determineGateVerdict, isAnchorInRegion } from '../curatedGeometryGate'

/**
 * Helper that mirrors what approveDisposition should do:
 * evaluate stored verification data against the canonical gate.
 * Returns the gate verdict and whether riderReady should be set.
 */
function evaluateApprovalCandidate(args: {
  anchorCount: number
  anchors: Array<{ lat: number; lng: number }>
  centroid: { lat: number; lng: number }
  routedMiles: number
  pointCount: number
  ratio: number | null
  quarantine: boolean
}): {
  verdict: 'pass' | 'review'
  failedCondition?: 'ratio' | 'anchors' | 'degenerate'
  riderReady: boolean
  gateResult: ReturnType<typeof determineGateVerdict>
} {
  // FIX-07: Count in-region anchors
  const inRegionAnchorCount = args.anchors.filter((a) =>
    isAnchorInRegion(a, args.centroid),
  ).length

  const gateResult = determineGateVerdict({
    ratio: args.ratio,
    pointCount: args.pointCount,
    routedMiles: args.routedMiles,
    anchorCount: args.anchorCount,
    inRegionAnchorCount,
    quarantine: args.quarantine,
  })

  return {
    verdict: gateResult.verdict,
    failedCondition: gateResult.failedCondition,
    riderReady: gateResult.verdict === 'pass',
    gateResult,
  }
}

const CENTROID = { lat: 34.95, lng: -120.42 }

describe('REDHAT-FIX-05: approvalGateEvaluation', () => {
  it('MUST_OBSERVE: passing candidate gets verdict:pass, riderReady:true', () => {
    // Two in-region anchors, good ratio, non-degenerate
    const result = evaluateApprovalCandidate({
      anchorCount: 2,
      anchors: [
        { lat: 34.96, lng: -120.42 }, // ~1.1 mi from centroid
        { lat: 34.94, lng: -120.44 }, // ~1.4 mi from centroid
      ],
      centroid: CENTROID,
      routedMiles: 41,
      pointCount: 100,
      ratio: 1.0,
      quarantine: false,
    })

    expect(result.verdict).toBe('pass')
    expect(result.riderReady).toBe(true)
    expect(result.failedCondition).toBeUndefined()
  })

  it('MUST_NOT: failing candidate (off-region anchors) does NOT get verdict:pass or riderReady:true', () => {
    // Anchors far outside 150mi region
    const result = evaluateApprovalCandidate({
      anchorCount: 2,
      anchors: [
        { lat: 40.0, lng: -120.42 }, // ~345 mi from centroid
        { lat: 40.1, lng: -120.42 }, // ~355 mi from centroid
      ],
      centroid: CENTROID,
      routedMiles: 41,
      pointCount: 100,
      ratio: 1.0,
      quarantine: false,
    })

    expect(result.verdict).toBe('review')
    expect(result.riderReady).toBe(false)
    expect(result.failedCondition).toBe('anchors')
  })

