    ids = fetchedIds.ids
    totalEligible = fetchedIds.totalEligible ?? ids.length
  }

  if (ids.length === 0) {
    return {
      classified: 0,
      failed: 0,
      results: [],
      totalEligible,
      remainingUnclassified: totalEligible,
    }
  }

  const results: ClassifyRouteResult[] = []
  for (const routeId of ids) {
